Future<String?> chooseAvatarImage()async{
 final file=await openFile(acceptedTypeGroups:[const XTypeGroup(label:'Images',extensions:['jpg','jpeg','png'],uniformTypeIdentifiers:['public.jpeg','public.png'])]);
 if(file==null)return null;
 if(await file.length()>2*1024*1024)throw const FormatException('Select a JPEG or PNG under 2 MB.');
 final bytes=await file.readAsBytes();final codec=await ui.instantiateImageCodec(bytes,targetWidth:256);final frame=await codec.getNextFrame();frame.image.dispose();codec.dispose();return base64Encode(bytes);
}
